let openMenu=document.getElementById("open-menu"),closeMenu=document.getElementById("close-menu"),menu=document.getElementById("menu");openMenu.addEventListener("click",()=>{menu.classList.remove("page__menu--hidden"),document.body.style.overflow="hidden",document.body.classList.add("page__body--menu-open")}),closeMenu.addEventListener("click",()=>{menu.classList.add("page__menu--hidden"),document.body.style.overflow="auto",document.body.classList.remove("page__body--menu-open")});